interface LearningStep {
  id: number;
  title: string;
  status: "completed" | "in-progress" | "locked";
}

export function Ruta({ steps }: { steps: LearningStep[] }) {
  return steps.map(s => <div key={s.id}>{s.title}</div>);
}

function linearSearchCount(arr, target) {
  let count = 0;
  for (let i = 0; i < arr.length; i++) {
    if (arr[i] === target) count++;
  }
  return count;
}

console.log(linearSearchCount([4, 2, 7, 2, 9, 2], 2)); // 3

function binarySearch(arr, target) {
  let left = 0, right = arr.length - 1;
  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) left = mid + 1;
    else right = mid - 1;
  }
  return -1;
}

function bubbleSort(arr) {
  const res = [...arr];
  for (let i = 0; i < res.length - 1; i++) {
    let swap = false;
    for (let j = 0; j < res.length - 1 - i; j++) {
      if (res[j] > res[j + 1]) {
        [res[j], res[j + 1]] = [res[j + 1], res[j]];
        swap = true;
      }
    }
    if (!swap) break;
  }
  return res;
}

function factorial(n) {
  if (n < 0) throw new Error("No negativos");
  if (n <= 1) return 1;
  return n * factorial(n - 1);
}

console.log(factorial(5)); // 120

function fibMemo(n, memo = {}) {
  if (n in memo) return memo[n];
  if (n <= 0) return 0;
  if (n === 1) return 1;
  memo[n] = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  return memo[n];
}

function estaBalanceado(texto) {
  const stack = [];
  for (const c of texto) {
    if (c === "(") stack.push(c);
    else if (c === ")") {
      if (stack.length === 0) return false;
      stack.pop();
    }
  }
  return stack.length === 0;
}

function sonCorreosUnicos(emails) {
  const setCorreos = new Set(emails);
  return setCorreos.size === emails.length;
}

console.log(sonCorreosUnicos(["a@x.com", "b@x.com", "a@x.com"])); // false

